package com.zpantry.recipe.domain;import com.zpantry.common.persistence.BaseEntity;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;
@Entity @Table(name="recipe_ingredients") public class RecipeIngredientEntity extends BaseEntity{@Column(name="recipe_id")public UUID recipeId;@Column(name="ingredient_id")public UUID ingredientId;@Column(precision=18,scale=4)public BigDecimal quantity;public String unit;@Column(name="is_required")public boolean required;public String note;protected RecipeIngredientEntity(){}public RecipeIngredientEntity(UUID r,UUID i,BigDecimal q,String u,boolean req,String n){recipeId=r;ingredientId=i;quantity=q;unit=u;required=req;note=n;}}
